import { PlaneGeometry, MeshBasicNodeMaterial, Mesh } from 'three/webgpu';

/**
 * Primary CTA node – a decorative plane with an engineered gradient + subtle grain texture.
 * Placed at the bottom of the home hub. No interactivity or cinematic primitives.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Mesh}
 */
export default function createNode(config, ctx) {
  // Load texture (synchronous cache hit in practice)
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');

  // Source rect is full image (0, 0, 512, 320) → no texture coordinate adjustment needed
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
  });

  const geometry = new PlaneGeometry(1, 1);

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -2.85, 0.2);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // No interactions, data bindings, or GSAP timelines
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
